customCSS:
.navLinks, #delform {
  position: relative;
  max-width: 1399px;
  margin: 0 auto;    
}

a {
  transition: color 0.1s ease-in-out;
}

#custom-board-list .current, #custom-board-list .current:hover {
  border: none !important;
}

#board-list #full-board-list .boardList {
  font-size: 10px !important;
}

#board-list #full-board-list .boardList .space {
  display: none !important;
}

.catalog-thread {
  border: 1px solid var(--sc-brderColor) !important;
}

:root.catalog-hover-expand .catalog-container.filter-highlight:hover>.post,
.catalog-thread:has(.filter-highlight),
#delform .filter-highlight>.post.op {
  border-color: rgb(var(--sc-postHLColor-rgb)) !important;
}

:root.catalog-hover-expand .watched>.catalog-container:hover>.post,
#delform .catalog-thread.watched {
  border-color: var(--sc-linkHColor) !important;
  border-width: 1px !important;
}

.catalog-thread.thread>.postContainer.catalog-container .catalog-thumb {
  box-shadow: none !important;
  border: none !important;
}

.replyContainer .inline {
  background-color: rgba(0,0,0,0.1) !important;
  margin: 8px 16px !important;
}

.replyContainer .inline .postMessage {
  word-break: break-word !important;
}
